<script lang="ts">import { open } from "@tauri-apps/plugin-dialog"; import type { InstanceForm } from "../../instance-form"; export let form: InstanceForm; async function choose(kind: "certificate" | "key") { const path = await open({ multiple: false, directory: false, filters: [{ name: kind === "certificate" ? "PEM certificate" : "PEM private key", extensions: ["pem", "crt", "cer", "key"] }] }); if (typeof path !== "string") return; if (kind === "certificate") form.xray_certificate_path = path; else form.xray_private_key_path = path; }</script>
<div class="form-grid equal"><label>Security<select bind:value={form.xray_security}><option value="reality">REALITY</option><option value="tls">TLS certificate</option></select></label><label>Transport<select bind:value={form.xray_transport}><option value="tcp">TCP</option><option value="xhttp">XHTTP</option>{#if form.xray_security === "tls"}<option value="mkcp">mKCP</option>{/if}</select></label></div><div class="form-grid equal"><label>SNI / camouflage host<input bind:value={form.xray_server_name} required placeholder="www.example.com" /></label><label>Client fingerprint<select bind:value={form.xray_fingerprint}><option value="chrome">Chrome</option><option value="firefox">Firefox</option><option value="safari">Safari</option><option value="edge">Edge</option><option value="randomized">Randomized</option></select></label></div>{#if form.xray_transport === "xhttp"}<label>XHTTP path<input bind:value={form.xray_xhttp_path} required placeholder="/" /></label>{/if}{#if form.xray_security === "tls"}<label>Certificate file<div class="path-input"><input value={form.xray_certificate_path} readonly placeholder="Choose a PEM certificate" /><button type="button" class="secondary" onclick={() => choose("certificate")}>Choose</button></div></label><label>Private-key file<div class="path-input"><input value={form.xray_private_key_path} readonly placeholder="Choose a PEM private key" /><button type="button" class="secondary" onclick={() => choose("key")}>Choose</button></div></label><p class="help">Choose both files for creation or replacement; leave both blank in Settings to retain existing material. Only paths cross the desktop bridge, and PEM contents never enter Svelte state.</p>{:else}<p class="help">REALITY private material is generated remotely during verified deployment. Only its public key and short ID are retained in desired state.</p>{/if}
